17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.time.LocalDate;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Optional;
24	import java.util.UUID;
25	
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.mapper.OwnerMapper;
32	import org.springframework.samples.petclinic.mapper.PetMapper;
33	import org.springframework.samples.petclinic.mapper.VisitMapper;
34	import org.springframework.samples.petclinic.model.Owner;
35	import org.springframework.samples.petclinic.model.Pet;
36	import org.springframework.samples.petclinic.model.Visit;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	    }
81	
82	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
83	    @Override
84	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
85	        Collection<Owner> owners;
86	        if (lastName != null) {
87	            owners = this.clinicService.findOwnerByLastName(lastName);
88	        } else {
89	            owners = this.clinicService.findAllOwners();
90	        }
91	        if (owners.isEmpty()) {
92	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
93	        }
94	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
100	        Owner owner = this.clinicService.findOwnerById(ownerId);
101	        if (owner == null) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
110	        HttpHeaders headers = new HttpHeaders();
111	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
112	        if (!normalizeNewOwner(owner)) {
113	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
114	        }
115	        if (dailyLimitReached(owner.getRegistrationDate())) {
116	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
117	        }
118	        if (cityIsAtCapacity(owner.getCity())) {
119	            return new ResponseEntity<>(HttpStatus.CONFLICT);
120	        }
121	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.CONFLICT);
123	        }
124	        Optional<Owner> householdMember = findHouseholdMember(owner);
125	        if (householdMember.isPresent()) {
126	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
127	                return new ResponseEntity<>(HttpStatus.CONFLICT);
128	            }
129	            joinHousehold(owner, householdMember.get());
130	        }
131	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
132	        owner.setNamesakeCount(countNamesakes(owner));
133	        owner.setMembershipNumber(membershipNumber(owner));
134	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
135	        this.clinicService.saveOwner(owner);
136	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
137	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
138	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
139	        headers.setLocation(UriComponentsBuilder.newInstance()
140	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
141	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
147	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
148	        if (currentOwner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        currentOwner.setAddress(ownerFieldsDto.getAddress());
152	        currentOwner.setCity(ownerFieldsDto.getCity());
153	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
154	        currentOwner.setLastName(ownerFieldsDto.getLastName());
155	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
156	        String email = ownerFieldsDto.getEmail();
157	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
158	        this.clinicService.saveOwner(currentOwner);
159	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Transactional
164	    @Override
165	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
166	        Owner owner = this.clinicService.findOwnerById(ownerId);
167	        if (owner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        this.clinicService.deleteOwner(owner);
171	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
177	        Owner owner = this.clinicService.findOwnerById(ownerId);
178	        if (owner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        HttpHeaders headers = new HttpHeaders();
182	        Pet pet = petMapper.toPet(petFieldsDto);
183	        owner.setId(ownerId);
184	        pet.setOwner(owner);
185	        pet.getType().setName(null);
186	        this.clinicService.savePet(pet);
187	        PetDto petDto = petMapper.toPetDto(pet);
188	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
189	            .buildAndExpand(pet.getId()).toUri());
190	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
196	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
197	        if (currentOwner != null) {
198	            Pet currentPet = this.clinicService.findPetById(petId);
199	            if (currentPet != null) {
200	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
201	                currentPet.setName(petFieldsDto.getName());
202	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
203	                this.clinicService.savePet(currentPet);
204	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
205	            }
206	        }
207	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
213	        HttpHeaders headers = new HttpHeaders();
214	        Visit visit = visitMapper.toVisit(visitFieldsDto);
215	        Pet pet = new Pet();
216	        pet.setId(petId);
217	        visit.setPet(pet);
218	        this.clinicService.saveVisit(visit);
219	        VisitDto visitDto = visitMapper.toVisitDto(visit);
220	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
221	            .buildAndExpand(visit.getId()).toUri());
222	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
223	    }
224	
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
229	        Owner owner = this.clinicService.findOwnerById(ownerId);
230	        if (owner != null) {
231	            Pet pet = owner.getPet(petId);
232	            if (pet != null) {
233	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
234	            }
235	        }
236	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	    }
238	
239	    /**
240	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
241	     * the canonical form each stored value must take: the address is trimmed,
242	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
243	     * telephone is converted to E.164, any email is lower-cased and a missing
244	     * registration date defaults to today. Field-level rejections are reported here
245	     * rather than inline in {@link #addOwner}, and normalisation runs before any
246	     * household comparison so those comparisons see the canonical values.
247	     *
248	     * @param owner the freshly-mapped owner to normalise
249	     * @return {@code true} if the fields are valid, or {@code false} if the address
250	     *         is blank after normalisation or the telephone cannot form a valid
251	     *         E.164 number, in which case the request must be rejected with
252	     *         {@code 400 Bad Request}
253	     */
254	    private boolean normalizeNewOwner(Owner owner) {
255	        String address = Owner.normalizeAddress(owner.getAddress());
256	        if (address.isEmpty()) {
257	            return false;
258	        }
259	        owner.setAddress(address);
260	        String telephone = toE164(owner.getTelephone());
261	        if (telephone == null) {
262	            return false;
263	        }
264	        owner.setTelephone(telephone);
265	        if (owner.getEmail() != null) {
266	            owner.setEmail(owner.getEmail().toLowerCase());
267	        }
268	        if (owner.getRegistrationDate() == null) {
269	            owner.setRegistrationDate(LocalDate.now());
270	        }
271	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
272	        return true;
273	    }
274	
275	    /**
276	     * Roll the given date forward to the next business day when it falls on a
277	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
278	     * weekday is returned unchanged. Applied to the effective registration date
279	     * (whether supplied in the request or defaulted to the server date) so that
280	     * every value derived from it uses the adjusted business day.
281	     *
282	     * @param date the effective registration date
283	     * @return the same date if it is a weekday, otherwise the next Monday
284	     */
285	    private static LocalDate rollToBusinessDay(LocalDate date) {
286	        switch (date.getDayOfWeek()) {
287	            case SATURDAY:
288	                return date.plusDays(2);
289	            case SUNDAY:
290	                return date.plusDays(1);
291	            default:
292	                return date;
293	        }
294	    }
295	
296	    /**
297	     * Find an existing owner that belongs to the same household as the given owner,
298	     * i.e. shares the same last name and address (compared case-insensitively with
299	     * runs of whitespace collapsed to a single space).
300	     *
301	     * @param owner the candidate owner being created
302	     * @return the matching existing owner, or empty if none exists
303	     */
304	    private Optional<Owner> findHouseholdMember(Owner owner) {
305	        return this.clinicService.findAllOwners().stream()
306	            .filter(existing -> existing.sameHouseholdAs(owner))
307	            .findFirst();
308	    }
309	
310	    /**
311	     * Assign the joining owner and an existing household member the same stable
312	     * household identifier. The identifier is derived deterministically from the
313	     * shared household key (last name + address, normalised), so every owner in a
314	     * household resolves to the same value; the existing member is updated when it
315	     * does not already carry it.
316	     *
317	     * @param owner    the owner being created
318	     * @param existing an existing owner in the same household
319	     */
320	    private void joinHousehold(Owner owner, Owner existing) {
321	        String householdId = UUID
322	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
323	        owner.setHouseholdId(householdId);
324	        if (!householdId.equals(existing.getHouseholdId())) {
325	            existing.setHouseholdId(householdId);
326	            this.clinicService.saveOwner(existing);
327	        }
328	    }
329	
330	    /**
331	     * Count the existing owners that share the given owner's first and last name,
332	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
333	     * before the new owner is saved, so the result reflects only owners that
334	     * already existed at creation time.
335	     *
336	     * @param owner the candidate owner being created
337	     * @return the number of existing namesakes
338	     */
339	    private int countNamesakes(Owner owner) {
340	        String firstName = normalizeName(owner.getFirstName());
341	        String lastName = normalizeName(owner.getLastName());
342	        return (int) this.clinicService.findAllOwners().stream()
343	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
344	                && normalizeName(existing.getLastName()).equals(lastName))
345	            .count();
346	    }
347	
348	    private static String normalizeName(String value) {
349	        return value == null ? "" : value.trim().toLowerCase();
350	    }
351	
352	    /**
353	     * Build the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>}: CITY3
354	     * is the upper-cased first three letters of the given city, LAST3 the upper-cased
355	     * first three letters of the given last name and NNNN a per-city 4-digit
356	     * zero-padded sequence equal to one more than the number of owners already in
357	     * that city (e.g. {@code SYD-SMI-0007}).
358	     *
359	     * @param city     the owner's city
360	     * @param lastName the owner's last name
361	     * @return the assigned customer code
362	     */
363	    /**
364	     * Determine whether the given city has already reached its owner capacity, i.e.
365	     * it already contains 50 or more existing owners (compared case-insensitively
366	     * with surrounding whitespace trimmed). A new owner may not be created in a city
367	     * that is at capacity.
368	     *
369	     * @param city the candidate owner's city
370	     * @return {@code true} if the city already holds 50 or more owners
371	     */
372	    private boolean cityIsAtCapacity(String city) {
373	        String normalizedCity = normalizeName(city);
374	        long count = this.clinicService.findAllOwners().stream()
375	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
376	            .count();
377	        return count >= 50;
378	    }
379	
380	    /**
381	     * Determine whether the daily owner-creation limit has already been reached, i.e.
382	     * 100 or more owners already carry the given registration date. A new owner may
383	     * not be created once that day's cap is reached.
384	     *
385	     * @param registrationDate the registration date the new owner would be created with
386	     * @return {@code true} if 100 or more existing owners share that registration date
387	     */
388	    private boolean dailyLimitReached(LocalDate registrationDate) {
389	        long count = this.clinicService.findAllOwners().stream()
390	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
391	            .count();
392	        return count >= 100;
393	    }
394	
395	    /**
396	     * Determine whether more than 80 owners have already been created for the given
397	     * registration date, i.e. strictly more than 80 existing owners carry that date.
398	     * Evaluated before the new owner is saved, so it reflects only owners that
399	     * already existed at creation time.
400	     *
401	     * @param registrationDate the registration date the new owner would be created with
402	     * @return {@code true} if more than 80 existing owners share that registration date
403	     */
404	    private boolean bulkSignupWarning(LocalDate registrationDate) {
405	        long count = this.clinicService.findAllOwners().stream()
406	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
407	            .count();
408	        return count > 80;
409	    }
410	
411	    private String nextCustomerCode(String city, String lastName) {
412	        String city3 = prefix3(city);
413	        String last3 = prefix3(lastName);
